<template><section class="page"><header class="head"><div><p class="eyebrow">Caisse sociale</p><h1>Demandes d’aide sociale</h1></div><router-link class="btn" to="/caisse-sociale/aides/nouveau">+ Demander une aide</router-link></header><div class="filters"><label>VOAMAMI<select v-model="voamamiId" @change="load"><option value="">Sélectionner</option><option v-for="v in voamamis" :key="v.id" :value="v.id">{{v.code}} — {{v.nom}}</option></select></label></div><p v-if="error" class="error">{{error}}</p><div class="table-wrap"><table><thead><tr><th>Membre</th><th>Type</th><th>Motif</th><th>Demandé</th><th>Accordé</th><th>Statut</th><th>Actions</th></tr></thead><tbody><tr v-for="a in rows" :key="a.id"><td>N°{{a.numero_membre}} — {{a.nom}} {{a.prenom||''}}</td><td>{{a.type_aide}}</td><td>{{a.motif}}</td><td>{{money(a.montant_demande)}}</td><td>{{money(a.montant_accorde)}}</td><td><span class="badge">{{a.statut}}</span></td><td class="actions"><template v-if="a.statut==='DEMANDEE' && isAdmin"><button @click="decide(a,'ACCORDEE')">Accorder</button><button @click="decide(a,'REFUSEE')">Refuser</button></template><button v-if="a.statut==='ACCORDEE' && isAdmin" @click="pay(a)">Marquer payée</button></td></tr><tr v-if="!rows.length"><td colspan="7" class="empty">Aucune demande.</td></tr></tbody></table></div></section></template>
<script setup>import{onMounted,ref,computed}from'vue';import caisseSocialeService from'../../service/caisse-sociale.service.js';import voamamiService from'../../service/voamami.service.js';import{useAuthStore}from'../../stores/auth.store.js';const auth=useAuthStore(),isAdmin=computed(()=>auth.user?.role==='ADMINISTRATEUR'),voamamis=ref([]),voamamiId=ref(''),rows=ref([]),error=ref('');const money=v=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:0}).format(Number(v||0))+' Ar';onMounted(async()=>{try{const{data}=await voamamiService.getAll();voamamis.value=data.data??[]}catch(e){error.value='Chargement impossible'}});async function load(){if(!voamamiId.value)return;try{const{data}=await caisseSocialeService.getAides(voamamiId.value);rows.value=data.data??[]}catch(e){error.value=e.response?.data?.message||'Chargement impossible'}}async function decide(a,statut){let montant=statut==='ACCORDEE'?prompt('Montant accordé (Ar)',a.montant_demande):null;if(statut==='ACCORDEE'&&(!montant||Number(montant)<=0))return;try{await caisseSocialeService.decideAide(a.id,{statut,montant_accorde:montant?Number(montant):null});await load()}catch(e){error.value=e.response?.data?.message||'Action impossible'}}async function pay(a){try{await caisseSocialeService.payerAide(a.id);await load()}catch(e){error.value=e.response?.data?.message||'Paiement impossible'}}</script>
<style scoped>.page{max-width:1200px;margin:auto;padding:2rem}.head{display:flex;justify-content:space-between;align-items:end;gap:1rem}.eyebrow{color:#2563eb;text-transform:uppercase;font-size:.75rem;font-weight:700}.btn{background:#2563eb;color:#fff;padding:.7rem 1rem;border-radius:.6rem;text-decoration:none}.filters{margin:1.5rem 0}.filters label{display:grid;max-width:320px;gap:.3rem;font-weight:600}select{padding:.7rem;border:1px solid #cbd5e1;border-radius:.5rem}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;background:#fff}th,td{padding:.75rem;text-align:left;border-bottom:1px solid #e2e8f0;white-space:nowrap}th{background:#f8fafc}.badge{background:#fef3c7;color:#92400e;padding:.25rem .5rem;border-radius:99px;font-size:.75rem}.actions{display:flex;gap:.4rem}.actions button{border:0;border-radius:.4rem;padding:.4rem .6rem;cursor:pointer}.empty{text-align:center;color:#64748b}.error{background:#fee2e2;color:#991b1b;padding:.7rem}@media(max-width:650px){.page{padding:1rem}.head{align-items:stretch;flex-direction:column}}
</style>
